  useEffect(()=>{const active=()=>{if(!sessionExpired)lastActivity.current=Date.now()};const events=["keydown","mousedown","mousemove","touchstart","scroll"] as const;events.forEach(event=>window.addEventListener(event,active,{passive:true}));const timer=setInterval(()=>{if(Date.now()-lastActivity.current>=3600000){safeStorage.set("prf-active-draft-v1",JSON.stringify(formRef.current));void saveIndexedDraft(formRef.current);setSessionExpired(true)}},60000);return()=>{events.forEach(event=>window.removeEventListener(event,active));clearInterval(timer)}},[sessionExpired]);
  useEffect(()=>{if(!creating)return;let active=true;setAccountingStatus("Loading every active FY27 site…");fetch("/api/accounting-codes?scope=all").then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load accounting codes");if(!active)return;const options=(data.options||[]) as AccountingCode[];setAccounting(options);const departments=new Set(options.filter(option=>option.source===DEPARTMENT_TAB).map(option=>option.siteKey)).size,schools=new Set(options.filter(option=>option.source===SCHOOL_TAB).map(option=>option.siteKey)).size;setAccountingStatus(options.length?`${departments+schools} active FY27 sites loaded — ${departments} departments / overhead and ${schools} school sites. Type to search by site name or code; the funding source fills in automatically.`:"No active accounting options found in the FY27 workbook")}).catch(error=>{if(active)setAccountingStatus(error.message)});return()=>{active=false}},[creating]);
  const mine=requests.filter(r=>r.requester==="Giselle Ajanel");
  const filtered=useMemo(()=>requests.filter(r=>(!filters.query||`${r.id} ${r.vendor} ${r.description}`.toLowerCase().includes(filters.query.toLowerCase()))&&(!filters.month||r.approvedAt?.startsWith(filters.month))&&(!filters.district||r.district===filters.district)&&(!filters.school||r.school===filters.school)&&(!filters.status||r.status===filters.status)&&(!filters.funding||r.fundingCode===filters.funding)),[requests,filters]);
  const save=(submit:boolean)=>{if(!form.vendor||!form.amount||!form.description){setNotice("Vendor, amount, and description are required.");return null}if(submit&&vague(form.description)){setNotice("Please detail specific items, quantities, and educational purpose.");return null}const amount=amountOf(form.amount);const activeId=editingIdRef.current;const id=activeId||nextPrfId(requestsRef.current);const now=new Date().toLocaleString();const prior=requests.find(r=>r.id===activeId);const item:Request={id,vendor:form.vendor,description:form.description,amount,status:"Draft",district:form.district,school:form.school,siteCode:form.siteCode,fundingCode:form.fundingCode,cycle:"FY2027 Cycle 01",requester:currentUser.fullName,updated:"Just now",lineItems:[{description:form.description,quantity:1,unitPrice:amount}],approvals:[],audit:[{time:now,event:"Draft saved",actor:currentUser.fullName},...(prior?.audit||[])],documents:prior?.documents||[]};setRequests(p=>activeId?p.map(r=>r.id===activeId?item:r):[item,...p]);if(!submit){editingIdRef.current=id;setEditingId(id);setNotice("Progress saved. You can safely leave and resume this PRF later.");setLastSaved("Saved just now");return item}safeStorage.remove("prf-active-draft-v1");editingIdRef.current=null;setEditingId(null);setNotice("");return item};
  const saveNativeDraft=()=>{const activeId=editingIdRef.current,id=activeId||nextPrfId(requestsRef.current),prior=requests.find(request=>request.id===activeId),amount=amountOf(form.amount);const item:Request={id,vendor:form.vendor||"Untitled vendor",description:form.description||"Native PRF draft in progress",amount,status:"Draft",district:form.district,school:form.school,siteCode:form.siteCode,fundingCode:form.fundingCode,cycle:"FY2027 Cycle 01",requester:currentUser.fullName,updated:"Just now",lineItems:form.lineItems.filter((line:any)=>line.description||line.amount).map((line:any)=>{const quantity=countOf(line.quantity)||1;return{description:line.description||"Line item",quantity,unitPrice:amountOf(line.amount)/quantity}}),approvals:[],audit:prior?.audit||[{time:new Date().toLocaleString(),event:"Native PRF draft created",actor:currentUser.fullName}],documents:prior?.documents||[]};setRequests(previous=>activeId?previous.map(request=>request.id===activeId?item:request):[item,...previous]);editingIdRef.current=id;setEditingId(id);safeStorage.set(`prf-editor-${id}`,JSON.stringify(form));setLastSaved("Saved just now");setNotice("Open Draft saved. You can close and resume it at any time.");return item};
  const resume=(rawRequest:Request)=>{const request=normalizeRequest(rawRequest);setEditingId(request.id);const stored=safeStorage.get(`prf-editor-${request.id}`);if(stored)try{const saved=JSON.parse(stored);setForm({...freshForm(),...saved,siteKey:saved.siteKey||siteKeyOf(saved.siteCode,saved.school),siteName:saved.siteName||saved.school||""});setCreating(true);return}catch{}const base=freshForm();setForm({...base,vendor:request.vendor,description:request.description,amount:String(request.amount),district:request.district,school:request.school,siteKey:siteKeyOf(request.siteCode,request.school),siteName:request.school,siteCode:request.siteCode,fundingCode:request.fundingCode,lineItems:Array.from({length:10},(_,index)=>{const line=request.lineItems[index];return line?{description:line.description,quantity:String(line.quantity),expenseType:"Program Supplies",club:"",splitSite:"",amount:String(line.quantity*line.unitPrice)}:blankLine()}),requestorName:request.requester,requestorSignature:request.requesterSigned?request.requester:""});setCreating(true)};
  const startNew=()=>{editingIdRef.current=null;setEditingId(null);setForm(freshForm());setAccounting([]);setAccountingStatus("Loading every active FY27 site…");setLastSaved("");setNotice("");safeStorage.remove("prf-active-draft-v1");safeStorage.remove("prf-active-draft-saved-at");void deleteIndexedDraft();setCreating(true)};
  const deleteDraft=(request:Request)=>{if(request.status!=="Draft")return;if(!window.confirm("Are you sure you want to delete this draft? This action cannot be undone."))return;setRequests(previous=>previous.filter(item=>item.id!==request.id));safeStorage.remove(`prf-editor-${request.id}`);if(editingIdRef.current===request.id){editingIdRef.current=null;setEditingId(null);setCreating(false);setForm(freshForm());safeStorage.remove("prf-active-draft-v1");safeStorage.remove("prf-active-draft-saved-at");void deleteIndexedDraft()}};
  useEffect(()=>{if(!creating||editingId)return;setForm(freshForm());setAccounting([]);setAccountingStatus("Loading every active FY27 site…");setLastSaved("");setNotice("");safeStorage.remove("prf-active-draft-v1");safeStorage.remove("prf-active-draft-saved-at");void deleteIndexedDraft()},[creating,editingId]);
  useEffect(()=>{const handle=(event:Event)=>{const id=(event as CustomEvent<string>).detail;const draft=requests.find(request=>request.id===id);if(draft)deleteDraft(draft)};window.addEventListener("delete-prf-draft",handle);return()=>window.removeEventListener("delete-prf-draft",handle)},[requests]);
  const submitNative=()=>{if(!form.requestorSignature||!form.requestorName||!form.requestorDate){setNotice("Add the requester name, signature, and date before submitting.");return}const item=save(false);if(!item)return;const now=new Date().toLocaleString();const submitted:Request={...item,status:"Awaiting Approval",requesterSigned:true,approvals:[{role:"Requester",name:form.requestorName,status:"Signed",time:now},{role:routeFor(item.amount),name:"Unassigned",status:"Pending"}],audit:[{time:now,event:"Native PRF electronically signed and submitted",actor:form.requestorName},...item.audit]};setRequests(previous=>previous.map(request=>request.id===item.id?submitted:request));safeStorage.set(`prf-editor-${item.id}`,JSON.stringify(form));safeStorage.remove("prf-active-draft-v1");setEditingId(null);editingIdRef.current=null;setCreating(false);setNotice("")};
